INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT137-S2-Q5$batch12$, 137, 2, 5, $batch12$Most Strongly Supported$batch12$, $batch12$The hormone testosterone protects brain cells from injury and reduces levels of the protein beta-amyloid in the brain. Beta-amyloid causally contributes to Alzheimer's disease, and people whose brain cells are susceptible to injury are probably more susceptible to Alzheimer's disease. So there is reason to think that _______.$batch12$, $batch12$Which one of the following most logically completes the argument?$batch12$, $batch12$E$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=137 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$anyone whose brain cells are susceptible to injury will eventually develop Alzheimer's disease$batch12$, $batch12$Too Strong$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$whether a person develops Alzheimer's disease is dependent entirely on the level of beta-amyloid in his or her brain$batch12$, $batch12$Too Strong$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Alzheimer's disease leads to a reduction in testosterone level$batch12$, $batch12$Reversed$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$only people with Alzheimer's disease are at risk for injury to brain cells$batch12$, $batch12$Too Strong$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$a decline in testosterone level puts one at increased risk for Alzheimer's disease$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Statements$batch12$, $batch12$Testosterone protects brain cells from injury and lowers beta-amyloid. Beta-amyloid contributes to Alzheimer's. Brain cells that are prone to injury probably raise Alzheimer's risk.$batch12$), (1, $batch12$Evaluate$batch12$, $batch12$Testosterone guards against two things that raise Alzheimer's risk. So less testosterone means less protection, and more risk.$batch12$), (2, $batch12$Goal$batch12$, $batch12$A decline in testosterone raises the risk of Alzheimer's.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Injury-prone cells probably raise susceptibility. That isn't certainty of developing the disease.$batch12$), ($batch12$B$batch12$, $batch12$Beta-amyloid contributes. Nothing says it is the only factor.$batch12$), ($batch12$C$batch12$, $batch12$The passage is about testosterone's effect on Alzheimer's risk, not the disease's effect on testosterone.$batch12$), ($batch12$D$batch12$, $batch12$Nothing says only people with Alzheimer's risk brain-cell injury.$batch12$), ($batch12$E$batch12$, $batch12$Testosterone reduces two contributors to Alzheimer's, so losing it raises the risk.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT137-S2-Q5$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
